#include "coordinate_point_common.hpp"
struct TP {int n,L;LD rate,Z;vector<LD>a,w;vector<vector<pair<int,LD>>>cdf;};
TP prepTree(const OG&g,int L,LD rate){TP p;p.L=L;p.n=L+1;p.rate=rate;int full=(1<<p.n)-1;p.a.resize(full+1);p.w.resize(full+1);p.cdf.resize(full+1);uint64_t inside[256]={};for(int s=1;s<=full;s++){int k=0;for(int i=0;i<p.n;i++)for(int j=i+1;j<p.n;j++,k++)if((s>>i&1)&&(s>>j&1))inside[s]|=1ULL<<(2*k);}
 for(int s=1;s<=full;s++){int v=__builtin_popcount(s);if(v==1){p.w[s]=1;continue;}int em=0;for(auto&t:g.g.terms){int e=__builtin_popcountll(t.key&inside[s])+2*__builtin_popcountll((t.key>>1)&inside[s]);em=max(em,e);}LD pow=v-1-em/2.L;p.a[s]=s==full?1:rate*max(.5L,abs(pow));int bit=s&-s;LD sum=0;for(int u=(s-1)&s;u;u=(u-1)&s)if(u&bit){int v=s^u;sum+=2*p.w[u]*p.w[v];p.cdf[s].push_back({u,sum});}p.w[s]=sum/p.a[s];}p.Z=p.w[full];return p;}
struct TreeSample {int n,L,ng,nn,leafn;int masks[28],gapnodes[7],parents[7],sizes[7],clusters[7],order[8];LD lt[7],alpha[7];};
TreeSample drawTree(const TP&p,const LD*u){TreeSample t{};t.n=p.n;t.L=p.L;int ci=0;function<void(int,int)>go=[&](int s,int parent){if(!(s&(s-1))){t.order[t.leafn++]=__builtin_ctz(s);return;}int id=t.nn++;t.parents[id]=parent;t.sizes[id]=__builtin_popcount(s);t.clusters[id]=s;LD v=u[ci++];if(id){t.alpha[id]=p.a[s];t.lt[id]=logl(u[p.L+id-1])/t.alpha[id];}else{t.alpha[id]=1;t.lt[id]=0;}bool flip=v>.5L;v=flip?2*v-1:2*v;LD z=v*p.cdf[s].back().second;auto it=lower_bound(p.cdf[s].begin(),p.cdf[s].end(),z,[](auto&a,LD b){return a.second<b;});if(it==p.cdf[s].end())--it;int A=it->first,B=s^A;if(flip)swap(A,B);go(A,id);t.gapnodes[t.ng++]=id;go(B,id);};go((1<<p.n)-1,-1);int pos[8];for(int i=0;i<p.n;i++)pos[t.order[i]]=i;int k=0;for(int i=0;i<p.n;i++)for(int j=i+1;j<p.n;j++){int lo=min(pos[i],pos[j]),hi=max(pos[i],pos[j]);t.masks[k++]=((1<<hi)-1)^((1<<lo)-1);}return t;}
template<class T>array<T,7> treePoint(const OG&g,int L,int K,const TreeSample&s,LD*rat){T scales[7],gap[7];scales[0]=1;T weight=1;for(int j=1;j<L;j++){T tt=expt(T(s.lt[j]));scales[j]=scales[s.parents[j]]*tt;weight*=expt(T((s.sizes[j]-1-s.alpha[j])*s.lt[j]));}for(int j=0;j<L;j++)gap[j]=scales[s.gapnodes[j]];int sz=1<<L;T dist[128]={},iv[28],logs[28];for(int mask=1;mask<sz;mask++){int bit=__builtin_ctz(mask);dist[mask]=dist[mask^(1<<bit)]+gap[bit];}int NE=L*(L+1)/2;for(int k=0;k<NE;k++){iv[k]=1/sqrtt(dist[s.masks[k]]);logs[k]=logt(dist[s.masks[k]])/2;}array<T,7>sum{};T absum[7]={};for(auto&t:g.terms){T H=0,R=0,base=1,lv=0;for(auto&e:t.e){int k=e[0],m=e[1];H+=m*dist[s.masks[k]];R+=e[2]*dist[s.masks[k]];T v=iv[k];if(m==1)base*=v;else if(m==2)base*=v*v;else base*=v*v*v;lv+=m*logs[k];}if(R==0)continue;base*=R/H;lv-=L*logt(H);for(int j=0;j<=K;j++){sum[j]+=base;absum[j]+=base<0?-base:base;base*=lv/(j+1);}}if(rat){*rat=1;for(int j=0;j<=K;j++)if(absum[j]>0)*rat=min(*rat,abs((LD)(sum[j]/absum[j])));}for(int j=0;j<=K;j++)sum[j]*=weight;return sum;}
